@dataclass
class GoodsReceiptNotesEntity21:
    """Data transfer object for Goods Receipt Note (GRN) Inwarding and Expiry Inspection - Segment 21."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
